"""Publish unchanged game captures, labelled reference images, and measured evidence."""
from pathlib import Path
import json,shutil,statistics,html,hashlib
from PIL import Image
from measure_perceived_detail import run,read
ROOT=Path('C:/GrandTour');QA=ROOT/'Saved/LidarAuthoringQA/PerceivedDetail';CAP=ROOT/'Saved/LidarAuthoringQA/RS7'
OUT=ROOT/'Art/Export/LidarStudy/FirstSection/Review/PerceivedDetail';OUT.mkdir(parents=True,exist_ok=True)
d=read(QA/'final-decision.json');pairs=[(run(a),run(b)) for a,b in d['pairs']]
views=pairs[0][0]['views'];metrics={}
for a,b in pairs:
 assert a['views']==b['views']==views and a['commands']==b['commands']
for v in views:
 name=v['view'];delta=[b['measurements'][name]['GPUTime']['median']-a['measurements'][name]['GPUTime']['median'] for a,b in pairs]
 metrics[name]=dict(before=statistics.median(a['measurements'][name]['GPUTime']['median'] for a,b in pairs),after=statistics.median(b['measurements'][name]['GPUTime']['median'] for a,b in pairs),median_paired_delta=statistics.median(delta),paired_deltas=delta,frame_p95_max=max(b['measurements'][name]['FrameTime']['p95'] for a,b in pairs))
 for side,label in [('before',d['before_label']),('after',d['after_label'])]:shutil.copy2(CAP/f'{label}-{name}.png',OUT/f'{side}-{name}.png')
refs=ROOT/'Art/References'
Image.open(refs/'ReferenceStyle/2026-11-05.jpg').crop((0,75,591,666)).save(OUT/'original-landscape-crop.png')
for src,name in [(refs/'Waimeamea/04_river_riffle_wading_ferns.jpg','site-bank.jpg'),(refs/'Waimeamea/08_bush_interior_crown_fern_pole_beech_mud.jpg','site-forest.jpg'),(refs/'Waimeamea/15_river_corner_warm_gravel_bar.jpg','site-gravel.jpg'),(refs/'ReferenceStyle/PhotoBased/waimeamea-bank-v03.png','approved-study.png')]:shutil.copy2(src,OUT/name)
evidence=dict(decision=d,validation=read(QA/'final-validation.json'),pairs=pairs,metrics=metrics,surface=read(QA/'surface-install.json'),stand=read(QA/'stand-proof.json'),shadow_proxy=read(QA/'shadow-proxy.json'),protected_files=read(QA/'protected-file-checks.json'),telemetry_summary=read(QA/'telemetry-summary.json'),persisted_config=read(QA/'persisted-config.json'),active_variant=read(QA/'active-variant.json'),visual_review=read(QA/'visual-review.json'),motion={name:read(OUT/(name+'-capture.json')) for name in ['bank-before','bank-after','forest-before','forest-after']},canopy_occlusion=read(QA/'canopy-occlusion-install.json'),map_sha256=hashlib.sha256((ROOT/'Content/GrandTour/ArtTests/LidarStudy/L_LidarStudy.umap').read_bytes()).hexdigest(),method='Actual standalone game. Same saved v6 preset, 1600x900 output, TSR75, fixed cameras. 180 warm frames per view excluding screenshot and recovery. Three A/B pairs in alternating order. Motion clips are deterministic camera reviews sampled at 12fps, not performance measurements.')
(OUT/'evidence.json').write_text(json.dumps(evidence,indent=2));shutil.copy2(QA/'gpu-telemetry.csv',OUT/'gpu-telemetry.csv')
names={'B01':'Near riverbank','B04':'Across the river','D01':'Fern detail','G01':'Ground detail','F01':'Forest edge','F02':'Inside the forest','T01':'Test stand'}
buttons=''.join(f'<button data-view="{v["view"]}">{names[v["view"]]}</button>' for v in views)
peak_memory=max(m['GPUMem/LocalUsedMB']['max'] for a,b in pairs for m in b['measurements'].values())
budget_memory=min(m['GPUMem/LocalBudgetMB']['median'] for a,b in pairs for m in b['measurements'].values())
gate=d['performance_gate'];gate_text=('Observed median +1 ms gate: '+('passed' if gate['observed_median_gate_passed'] else 'not passed')+'. Maximum median paired increase '+format(gate['maximum_median_paired_delta_ms'],'.2f')+' ms. Thermal variation remains a limitation.')
rows=''.join(f'<tr><td>{names[k]}</td><td>{m["before"]:.2f}</td><td>{m["after"]:.2f}</td><td>{m["median_paired_delta"]:+.2f}</td></tr>' for k,m in metrics.items())
decisions=''.join(f'<li>{html.escape(t)}</li>' for t in d['retained'])
rejected=''.join(f'<li>{html.escape(t)}</li>' for t in d['rejected'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Riverbank and forest detail — actual game review</title>
<style>*{box-sizing:border-box}body{margin:0;background:#121c19;color:#ecf2e9;font:16px/1.5 system-ui}main{max-width:1800px;margin:auto;padding:26px}h1{font-size:30px;margin:0}p{color:#bfcec3}a{color:#afe0c2}nav{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}button,select{font:inherit;background:#243b30;color:#edf3e8;border:1px solid #54725e;border-radius:5px;padding:8px 12px;cursor:pointer}button[aria-pressed=true]{background:#50764e}.layout{display:grid;grid-template-columns:minmax(0,3fr) minmax(260px,1fr);gap:24px}.compare{position:relative;aspect-ratio:16/9;overflow:hidden;background:#07100d}.compare img{position:absolute;width:100%;height:100%;object-fit:contain}.compare b{position:absolute;top:12px;background:#0a171ddd;padding:5px 9px;border-radius:3px;font-size:14px}.before-label{left:12px}.after-label{right:12px}.line{position:absolute;top:0;bottom:0;width:2px;background:white;left:50%}.controls{display:flex;gap:12px;align-items:center;margin:12px 0}.controls input{flex:1;accent-color:#a6d58a}aside img{width:100%;max-height:620px;object-fit:contain;background:#07100d}aside select{width:100%;margin-bottom:12px}aside p{font-size:14px}.notes{display:grid;grid-template-columns:1fr 1fr;gap:32px;max-width:1200px}.clips{display:grid;grid-template-columns:1fr 1fr;gap:22px}video{width:100%;background:#000}table{border-collapse:collapse}td,th{text-align:left;padding:7px 20px 7px 0;border-bottom:1px solid #3d5144}h2{font-size:21px;margin-top:28px}@media(max-width:1000px){.layout,.notes,.clips{grid-template-columns:1fr}aside img{max-height:480px}} </style>
<main><h1>Riverbank and forest · detail in the actual game</h1><p>@@SUMMARY@@</p><p>Scope: a 4 × 4 m ground patch, one fern variant, and 48 existing beech trees. Same scene, planting, sun, fog, exposure and base graphics preset. The candidate also enables TSR thin-geometry detection. Original LOD meshes provide shadows for the 48-tree test in both comparisons.</p><nav>@@BUTTONS@@</nav>
<div class="layout"><section><div class="compare"><img id="before" alt="Baseline game capture"><img id="after" alt="Retained detail game capture"><div class="line" id="line"></div><b class="before-label">Before</b><b class="after-label">After</b></div><div class="controls"><button id="onlyBefore">Before</button><input id="split" aria-label="Before and after split" type="range" min="0" max="100" value="50"><button id="onlyAfter">After</button></div><p id="timing"></p><p><a id="fullBefore">Full-size before</a> · <a id="fullAfter">Full-size after</a></p></section>
<aside><select id="reference" aria-label="Reference"><option value="original-landscape-crop.png">Original style — colour and variety</option><option value="site-bank.jpg">Site photo 04 — riverbank</option><option value="site-forest.jpg">Site photo 08 — forest floor</option><option value="site-gravel.jpg">Site photo 15 — gravel and moss</option><option value="approved-study.png">Approved photo-based study</option></select><img id="ref" src="original-landscape-crop.png" alt="Selected project reference"><p id="refNote">Landscape crop of the original supplied reference. The game images at left are unretouched captures.</p></aside></div>
<div class="notes"><section><h2>Retained</h2><ul>@@RETAINED@@</ul><h2>Not promoted</h2><ul>@@REJECTED@@</ul></section><section><h2>Measured cost</h2><p><strong>@@GATE@@</strong></p><table><thead><tr><th>View</th><th>Before ms</th><th>After ms</th><th>Paired Δ ms</th></tr></thead><tbody>@@ROWS@@</tbody></table><p>GPU medians from three warmed A/B pairs. Paired changes are aggregated by median within the three run pairs; this need not equal the difference of the pooled before/after medians. These bounded views do not certify the full world or a target frame rate.</p><p>Peak local GPU memory in measured candidate windows: @@MEMORY@@. This is measured residency against the available local budget, not total hardware capacity.</p><p>@@LIMITATIONS@@</p><p><a href="evidence.json">Full validation and timings</a> · <a href="gpu-telemetry.csv">GPU clocks, temperature and memory</a></p></section></div>
<h2>Motion comparison</h2><p>Actual game viewport samples. Camera review at 12 fps; performance comes from the separate profiling runs above.</p><div class="clips"><section><h3>Bank — before</h3><video controls muted preload="metadata" src="bank-before.mp4"></video></section><section><h3>Bank — after</h3><video controls muted preload="metadata" src="bank-after.mp4"></video></section><section><h3>Forest — before</h3><video controls muted preload="metadata" src="forest-before.mp4"></video></section><section><h3>Forest — after</h3><video controls muted preload="metadata" src="forest-after.mp4"></video></section></div><p><a href="../index.html">Earlier section and reference reviews</a></p></main>
<script>const metrics=@@METRICS@@;const split=document.getElementById('split');function update(){document.getElementById('after').style.clipPath=`inset(0 0 0 ${split.value}%)`;document.getElementById('line').style.left=split.value+'%'}split.oninput=update;document.getElementById('onlyBefore').onclick=()=>{split.value=100;update()};document.getElementById('onlyAfter').onclick=()=>{split.value=0;update()};function choose(v){for(const side of ['before','after']){document.getElementById(side).src=side+'-'+v+'.png';document.getElementById('full'+side[0].toUpperCase()+side.slice(1)).href=side+'-'+v+'.png'}for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-pressed',b.dataset.view===v);const m=metrics[v];document.getElementById('timing').textContent='Median paired GPU change in this view: '+(m.median_paired_delta>=0?'+':'')+m.median_paired_delta.toFixed(2)+' ms.'}for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>choose(b.dataset.view);document.getElementById('reference').onchange=e=>{document.getElementById('ref').src=e.target.value;document.getElementById('refNote').textContent=e.target.value==='approved-study.png'?'Photo-based visual study; this is a reference, not a game capture.':e.target.value==='original-landscape-crop.png'?'Landscape crop of the original supplied reference. The game images at left are unretouched captures.':'User-supplied site photograph. The game images at left are unretouched captures.'};choose('T01');update();</script></html>'''
for key,value in {'SUMMARY':html.escape(d['summary']),'BUTTONS':buttons,'RETAINED':decisions,'REJECTED':rejected,'ROWS':rows,'LIMITATIONS':html.escape(d['limitations']),'METRICS':json.dumps(metrics),'GATE':html.escape(gate_text),'MEMORY':f'{peak_memory:.0f} / {budget_memory:.0f} MB'}.items():page=page.replace('@@'+key+'@@',value)
(OUT/'index.html').write_text(page,encoding='utf-8')
assert '@@' not in page
print(json.dumps(dict(review=str(OUT/'index.html'),metrics=metrics),indent=2))
